// The WideField GPU kernels (adapter/inSiliScope/Simulation/WidefieldGpu.wgsl), for web/wf_gpu.js.
self.ISC_WF_WGSL = "// WidefieldGpu.wgsl -- the WideField GPU kernels (spec/PORT.md 13), ONE source\n// for both GPU paths: WebGPU in the viewer (web/wf_gpu.js) and Direct3D 11 in\n// the adapter (Simulation/WidefieldGpuD3D11.cpp), whose HLSL is generated from\n// this file by naga (tools/gen_wf_gpu.mjs; never hand-edit the generated\n// WidefieldGpuHlsl.inc).\n//\n// The file is a set of modules: \"//// common\" is prepended to every\n// \"//// kernel <name>\" section, and each section is compiled on its own (its\n// bindings, group 0, are its own). The entry point is named like the section.\n//\n// Pipeline (WidefieldScene::MakeGpuJob describes the work):\n//   wf_clear, wf_scatter    two dye planes' weighted counts -> one complex grid\n//                            (plane A real, plane B imaginary)\n//   wf_fft (rows, columns)  radix-2 in workgroup memory, n <= 2048\n//   wf_split                Hermitian split into the two planes' half spectra,\n//                            stored as fp16 pairs scaled by 1 / sum|values|\n//   wf_mac                  per channel: sum over its dye planes of\n//                            A_k (w0 K_p0 + w1 K_p1)   (the focus re-pairing)\n//   wf_expand               two channels -> one full complex spectrum with the\n//                            sub-cell phase ramp (Nyquist bins: cosine)\n//   wf_fft (inverse)        rows, columns\n//   wf_crop                 the FOV cells of both channels (1 / (nx ny))\n//   wf_frame                bin(max(0, P + sum_j a_j B_j)) + background, then\n//                            the camera noise chain -- the counter-based pcg4d\n//                            stream of SMLMCounterRng.h, mirrored LINE FOR LINE\n//                            (change one, change all three: this, the HLSL of\n//                            GpuSimD3D11.cpp, SMLMCounterRng.h)\n\n//// common\n\nconst kNone: u32 = 0xffffffffu;\n\nfn cmul(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {\n   return vec2<f32>(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);\n}\n\nfn conj2(a: vec2<f32>) -> vec2<f32> {\n   return vec2<f32>(a.x, -a.y);\n}\n\n//// kernel wf_clear\n\nstruct ClearParams { count: u32, rowLen: u32, p2: u32, p3: u32 }\n@group(0) @binding(0) var<uniform> P: ClearParams;\n@group(0) @binding(1) var<storage, read_write> data: array<vec2<f32>>;\n\n@compute @workgroup_size(256)\nfn wf_clear(@builtin(global_invocation_id) g: vec3<u32>) {\n   let i = g.x + g.y * P.rowLen;\n   if (i < P.count) {\n      data[i] = vec2<f32>(0.0, 0.0);\n   }\n}\n\n//// kernel wf_scatter\n\n// entries: (grid slot, cell = y * nx + x, bitcast value, component 0 re / 1 im)\nstruct ScatterParams { count: u32, nx: u32, NX: u32, planeStride: u32, rowLen: u32, p1: u32, p2: u32, p3: u32 }\n@group(0) @binding(0) var<uniform> P: ScatterParams;\n@group(0) @binding(1) var<storage, read> entries: array<vec4<u32>>;\n@group(0) @binding(2) var<storage, read_write> data: array<vec2<f32>>;\n\n@compute @workgroup_size(256)\nfn wf_scatter(@builtin(global_invocation_id) g: vec3<u32>) {\n   let i = g.x + g.y * P.rowLen;\n   if (i >= P.count) {\n      return;\n   }\n   let e = entries[i];\n   let x = e.y % P.nx;\n   let y = e.y / P.nx;\n   let idx = e.x * P.planeStride + y * P.NX + x;\n   let v = bitcast<f32>(e.z);\n   if (e.w == 0u) {\n      data[idx].x = v;\n   } else {\n      data[idx].y = v;\n   }\n}\n\n//// kernel wf_fft\n\n// Transform t (workgroup x) of plane z: elements base + i * elemStride,\n// base = z * planeStride + t * xfStride. Iterative radix-2 in workgroup\n// memory (bit-reversed load); twiddles exp(-2 pi i k / n) at twOff.\nstruct FftParams { n: u32, logn: u32, elemStride: u32, xfStride: u32, planeStride: u32, inverse: u32, twOff: u32, p7: u32 }\n@group(0) @binding(0) var<uniform> P: FftParams;\n@group(0) @binding(1) var<storage, read_write> data: array<vec2<f32>>;\n@group(0) @binding(2) var<storage, read> tw: array<vec2<f32>>;\n\nvar<workgroup> buf: array<vec2<f32>, 2048>;\n\n@compute @workgroup_size(256)\nfn wf_fft(@builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>) {\n   let base = wid.z * P.planeStride + wid.x * P.xfStride;\n   let shift = 32u - P.logn;\n   for (var i = lid.x; i < P.n; i += 256u) {\n      buf[reverseBits(i) >> shift] = data[base + i * P.elemStride];\n   }\n   workgroupBarrier();\n   var half = 1u;\n   for (var s = 0u; s < P.logn; s++) {\n      let step = P.n / (2u * half);\n      for (var j = lid.x; j < P.n / 2u; j += 256u) {\n         let k = j % half;\n         let i0 = (j / half) * 2u * half + k;\n         let i1 = i0 + half;\n         var w = tw[P.twOff + k * step];\n         if (P.inverse != 0u) {\n            w.y = -w.y;\n         }\n         let a = buf[i0];\n         let b = cmul(buf[i1], w);\n         buf[i0] = a + b;\n         buf[i1] = a - b;\n      }\n      workgroupBarrier();\n      half = half * 2u;\n   }\n   for (var i = lid.x; i < P.n; i += 256u) {\n      data[base + i * P.elemStride] = buf[i];\n   }\n}\n\n//// kernel wf_split\n\n// Grid pair z holds Z = F(a + i b); A = (Z[k] + conj Z[-k]) / 2,\n// B = (Z[k] - conj Z[-k]) / 2i, stored (half spectrum, kx <= NX/2) as fp16\n// pairs times invScale. slots[z] = (slot A, slot B or none, invScale A,\n// invScale B as bits).\nstruct SplitParams { NX: u32, NY: u32, W: u32, SS: u32, PS: u32, pairs: u32, p6: u32, p7: u32 }\n@group(0) @binding(0) var<uniform> P: SplitParams;\n@group(0) @binding(1) var<storage, read> data: array<vec2<f32>>;\n@group(0) @binding(2) var<storage, read> slots: array<vec4<u32>>;\n@group(0) @binding(3) var<storage, read_write> spec: array<u32>;\n\n@compute @workgroup_size(16, 16)\nfn wf_split(@builtin(global_invocation_id) g: vec3<u32>) {\n   let kx = g.x;\n   let ky = g.y;\n   if (kx >= P.W || ky >= P.NY) {\n      return;\n   }\n   let z = g.z;\n   let base = z * P.PS;\n   let zk = data[base + ky * P.NX + kx];\n   let zm = conj2(data[base + ((P.NY - ky) % P.NY) * P.NX + (P.NX - kx) % P.NX]);\n   let s = slots[z];\n   let bin = ky * P.W + kx;\n   let a = 0.5 * (zk + zm);\n   spec[s.x * P.SS + bin] = pack2x16float(a * bitcast<f32>(s.z));\n   if (s.y != kNone) {\n      let d = 0.5 * (zk - zm);\n      // (Zk - conj Zm) / 2i\n      spec[s.y * P.SS + bin] = pack2x16float(vec2<f32>(d.y, -d.x) * bitcast<f32>(s.w));\n   }\n}\n\n//// kernel wf_mac\n\n// Channel z: bins of sum over deps[chan.x .. chan.x + chan.y) of\n// A_plane * scale (w0 K_k0 + w1 K_k1). depI = (plane slot, k0, k1 or none,\n// scale bits), depW = (w0, w1).\nstruct MacParams { SS: u32, nChan: u32, rowLen: u32, p3: u32 }\n@group(0) @binding(0) var<uniform> P: MacParams;\n@group(0) @binding(1) var<storage, read> spec: array<u32>;\n@group(0) @binding(2) var<storage, read> kspec: array<vec2<f32>>;\n@group(0) @binding(3) var<storage, read> depI: array<vec4<u32>>;\n@group(0) @binding(4) var<storage, read> depW: array<vec2<f32>>;\n@group(0) @binding(5) var<storage, read> chans: array<vec2<u32>>;\n@group(0) @binding(6) var<storage, read_write> out: array<vec2<f32>>;\n\n@compute @workgroup_size(256)\nfn wf_mac(@builtin(global_invocation_id) g: vec3<u32>) {\n   let bin = g.x + g.y * P.rowLen;\n   if (bin >= P.SS) {\n      return;\n   }\n   let c = chans[g.z];\n   var acc = vec2<f32>(0.0, 0.0);\n   for (var d = c.x; d < c.x + c.y; d++) {\n      let di = depI[d];\n      let dw = depW[d];\n      let a = unpack2x16float(spec[di.x * P.SS + bin]) * bitcast<f32>(di.w);\n      var k = dw.x * kspec[di.y * P.SS + bin];\n      if (di.z != kNone) {\n         k = k + dw.y * kspec[di.z * P.SS + bin];\n      }\n      acc = acc + cmul(a, k);\n   }\n   out[g.z * P.SS + bin] = acc;\n}\n\n//// kernel wf_expand\n\n// Pair z = (channel c1, channel c2 or none): Z = S1 ph + i S2 ph over the\n// whole grid (the other half from Hermitian symmetry); ph = exp(+2 pi i kx\n// fracX / NX) exp(+2 pi i ky fracY / NY), each factor's cosine on its axis's\n// Nyquist bin (so the shifted spectrum stays Hermitian).\nstruct ExpandParams { NX: u32, NY: u32, W: u32, SS: u32, PS: u32, pairs: u32, fracX: f32, fracY: f32 }\n@group(0) @binding(0) var<uniform> P: ExpandParams;\n@group(0) @binding(1) var<storage, read> chan: array<vec2<f32>>;\n@group(0) @binding(2) var<storage, read> pairs: array<vec2<u32>>;\n@group(0) @binding(3) var<storage, read_write> data: array<vec2<f32>>;\n\nfn halfBin(c: u32, x: u32, y: u32) -> vec2<f32> {\n   if (x < P.W) {\n      return chan[c * P.SS + y * P.W + x];\n   }\n   return conj2(chan[c * P.SS + ((P.NY - y) % P.NY) * P.W + (P.NX - x)]);\n}\n\n@compute @workgroup_size(16, 16)\nfn wf_expand(@builtin(global_invocation_id) g: vec3<u32>) {\n   let x = g.x;\n   let y = g.y;\n   if (x >= P.NX || y >= P.NY) {\n      return;\n   }\n   let pr = pairs[g.z];\n   var kx = f32(x);\n   if (x > P.NX / 2u) {\n      kx = kx - f32(P.NX);\n   }\n   var ky = f32(y);\n   if (y > P.NY / 2u) {\n      ky = ky - f32(P.NY);\n   }\n   // Separable per axis, the cosine on an axis's Nyquist bin (as the CPU).\n   let ax = 6.283185307179586 * kx * P.fracX / f32(P.NX);\n   let ay = 6.283185307179586 * ky * P.fracY / f32(P.NY);\n   var px = vec2<f32>(cos(ax), sin(ax));\n   if (x == P.NX / 2u) {\n      px.y = 0.0;\n   }\n   var py = vec2<f32>(cos(ay), sin(ay));\n   if (y == P.NY / 2u) {\n      py.y = 0.0;\n   }\n   let ph = cmul(px, py);\n   let s1 = cmul(halfBin(pr.x, x, y), ph);\n   var z = s1;\n   if (pr.y != kNone) {\n      let s2 = cmul(halfBin(pr.y, x, y), ph);\n      z = vec2<f32>(s1.x - s2.y, s1.y + s2.x);\n   }\n   data[g.z * P.PS + y * P.NX + x] = z;\n}\n\n//// kernel wf_crop\n\n// Pair z's FOV cells: real part -> image of c1, imaginary -> image of c2\n// (images are cw x ch, channel c at c * cw * ch), times 1 / (NX NY).\nstruct CropParams { NX: u32, PS: u32, fovX0: u32, fovY0: u32, cw: u32, ch: u32, scale: f32, p7: u32 }\n@group(0) @binding(0) var<uniform> P: CropParams;\n@group(0) @binding(1) var<storage, read> data: array<vec2<f32>>;\n@group(0) @binding(2) var<storage, read> pairs: array<vec2<u32>>;\n@group(0) @binding(3) var<storage, read_write> imgs: array<f32>;\n\n@compute @workgroup_size(16, 16)\nfn wf_crop(@builtin(global_invocation_id) g: vec3<u32>) {\n   if (g.x >= P.cw || g.y >= P.ch) {\n      return;\n   }\n   let pr = pairs[g.z];\n   let v = data[g.z * P.PS + (P.fovY0 + g.y) * P.NX + P.fovX0 + g.x] * P.scale;\n   let i = g.y * P.cw + g.x;\n   let cs = P.cw * P.ch;\n   imgs[pr.x * cs + i] = v.x;\n   if (pr.y != kNone) {\n      imgs[pr.y * cs + i] = v.y;\n   }\n}\n\n//// kernel wf_frame\n\n// Camera pixel (x, y) of batch frame z: the dyes (images: [persistent],\n// bleach maps; coef: nB per frame) binned over upscale^2 cells, plus the\n// background, then the sCMOS or EMCCD noise chain (ApplyNoiseChain).\nstruct FrameParams {\n   W: u32, H: u32, cw: u32, u: u32,\n   nB: u32, hasP: u32, nFrames: u32, seed: u32,\n   emccd: u32, qe: f32, dark: f32, cic: f32,\n   emGain: f32, maxAdu: f32, p14: u32, p15: u32,\n}\n@group(0) @binding(0) var<uniform> P: FrameParams;\n@group(0) @binding(1) var<storage, read> imgs: array<f32>;\n@group(0) @binding(2) var<storage, read> coef: array<f32>;\n@group(0) @binding(3) var<storage, read> frames: array<vec2<u32>>; // frame id, background scale bits\n@group(0) @binding(4) var<storage, read> pix: array<vec4<f32>>;   // offset ADU, gain photons/ADU, read noise e-, background\n@group(0) @binding(5) var<storage, read_write> out: array<u32>;\n\nvar<private> gFrame: u32;\nvar<private> gPix: u32;\nvar<private> gCtr: u32;\nvar<private> gBuf: vec4<u32>;\nvar<private> gK: u32;\n\nfn pcg4d(vin: vec4<u32>) -> vec4<u32> {\n   var v = vin * 1664525u + vec4<u32>(1013904223u);\n   v.x += v.y * v.w;\n   v.y += v.z * v.x;\n   v.z += v.x * v.y;\n   v.w += v.y * v.z;\n   v = v ^ (v >> vec4<u32>(16u));\n   v.x += v.y * v.w;\n   v.y += v.z * v.x;\n   v.z += v.x * v.y;\n   v.w += v.y * v.z;\n   return v;\n}\n\nfn uniform01() -> f32 {\n   if (gK == 4u) {\n      gBuf = pcg4d(vec4<u32>(P.seed, gFrame, gPix, gCtr));\n      gCtr = gCtr + 1u;\n      gK = 0u;\n   }\n   let x = gBuf[gK];\n   gK = gK + 1u;\n   return (f32(x >> 9u) + 0.5) * 1.1920928955078125e-7;\n}\n\nfn gauss() -> f32 {\n   let r = sqrt(-2.0 * log(uniform01()));\n   return r * cos(6.283185307179586 * uniform01());\n}\n\nfn poisson(l: f32) -> f32 {\n   if (l > 60.0) {\n      return max(0.0, floor(l + sqrt(l) * gauss() + 0.5));\n   }\n   if (!(l > 0.0)) {\n      return 0.0;\n   }\n   let L = exp(-l);\n   var k = 0;\n   var p = 1.0;\n   loop {\n      k = k + 1;\n      p = p * uniform01();\n      if (!(p > L && k < 1000)) {\n         break;\n      }\n   }\n   return f32(k - 1);\n}\n\nfn gammaDraw(k: f32) -> f32 {\n   let d = k - 1.0 / 3.0;\n   let c = 1.0 / sqrt(9.0 * d);\n   for (var it = 0; it < 1000; it++) {\n      let x = gauss();\n      let t = 1.0 + c * x;\n      if (t <= 0.0) {\n         continue;\n      }\n      let v = t * t * t;\n      let w = uniform01();\n      if (w < 1.0 - 0.0331 * x * x * x * x) {\n         return d * v;\n      }\n      if (log(w) < 0.5 * x * x + d * (1.0 - v + log(v))) {\n         return d * v;\n      }\n   }\n   return d;\n}\n\n@compute @workgroup_size(16, 16)\nfn wf_frame(@builtin(global_invocation_id) g: vec3<u32>) {\n   if (g.x >= P.W || g.y >= P.H || g.z >= P.nFrames) {\n      return;\n   }\n   let i = g.y * P.W + g.x;\n   let px = pix[i];\n   let fr = frames[g.z];\n   let cs = P.cw * (P.H * P.u);\n   var dyes = 0.0;\n   for (var sy = 0u; sy < P.u; sy++) {\n      for (var sx = 0u; sx < P.u; sx++) {\n         let c = (g.y * P.u + sy) * P.cw + g.x * P.u + sx;\n         var v = 0.0;\n         if (P.hasP != 0u) {\n            v = imgs[c];\n         }\n         for (var j = 0u; j < P.nB; j++) {\n            v = v + coef[g.z * P.nB + j] * imgs[(P.hasP + j) * cs + c];\n         }\n         dyes = dyes + max(0.0, v);\n      }\n   }\n   let photons = max(px.w * bitcast<f32>(fr.y) + dyes, 0.0);\n\n   gFrame = fr.x;\n   gPix = i;\n   gCtr = 0u;\n   gK = 4u;\n   gBuf = vec4<u32>(0u, 0u, 0u, 0u);\n   var adu: f32;\n   if (P.emccd != 0u) {\n      let ne = poisson(photons * P.qe + P.dark + P.cic);\n      var o = 0.0;\n      if (ne > 0.0) {\n         o = gammaDraw(ne);\n      }\n      adu = floor(px.x + (o + (px.z / P.emGain) * gauss()) / px.y + 0.5);\n      adu = clamp(adu, 0.0, P.maxAdu);\n   } else {\n      let ne = poisson(photons * P.qe + P.dark);\n      adu = px.x + (ne + px.z * gauss()) / px.y;\n      adu = floor(clamp(adu, 0.0, 65535.0) + 0.5);\n   }\n   out[g.z * P.W * P.H + i] = u32(adu);\n}\n";
// The blink splat + camera noise (adapter/inSiliScope/Simulation/SplatGpu.wgsl), for web/splat_gpu.js.
self.ISC_SPLAT_WGSL = "// SPDX-License-Identifier: BSD-3-Clause\n// The blink splat + camera noise, fused: the WGSL twin of the adapter's HLSL kernel (GpuSimD3D11.cpp kShaderSource),\n// run by SplatGpuHost (SplatGpu.cpp) on the viewer's WebGPU (cli/gpu_js_backend.cpp, web/splat_gpu.js).\n// One invocation per output pixel gathers its frame's emitters from the kernels' block sums (PsfKernelCache::BlockSums,\n// row-major per plane: the numbers the CPU splat reads, with SplatSetup's indices and weights), adds the frame's other\n// light (Extra: what the CPU renders besides the splatted blinks: the background, the continuous populations, binned\n// blinks), and applies the sCMOS or EMCCD noise chain with the counter-based pcg4d stream of SMLMCounterRng.h, mirrored\n// line for line (change one, change all three). Frames equal the CPU's up to float32 rounding.\n//\n// Bindings (seven storage buffers: within WebGPU's default limit of eight):\n//   0  P     the parameters (64 bytes)\n//   1-4 S0..S3 the kernels' block sums (one buffer per distinct kernel: a default one is ~200 MB)\n//   5  Stat  per pixel: offset ADU, gain photons/ADU, read noise e-, background photons before the fade (f32 bits);\n//            then the halo cut's spans (columns [lo, hi] per (plane, dy)) from word P.spanAt\n//   6  Dyn   words 0..31: the kernel table (KGeo[4] = camera radius, oversampling, block-sum width, offset; KMisc[4] =\n//            plane stride, spans on, first span, buffer); then 8 words per frame (emitter start, count, frame, bgScale,\n//            extra start or 0xffffffff, tile table start); then the emitters (16 words each, GpuSplatEmitter); then per\n//            frame its extra image and its tile table (per 16 x 16 tile, row-major, the word position of its list, one\n//            more for the end; then the lists: emitter numbers)\n//   7  Out   the frames' ADU, frame k at k * W * H\n\n//// kernel splat_frames\nstruct Params\n{\n   W: u32, H: u32, NFrames: u32, Seed: u32,\n   Emccd: u32, Qe: f32, Dark: f32, Cic: f32,\n   EmGain: f32, MaxAdu: f32, PixBase: u32, SpanAt: u32,\n   EmAt: u32, Pad0: u32, Pad1: u32, Pad2: u32,\n};\n\nstruct Em\n{\n   x0: i32, y0: i32, bx: i32, by: i32,\n   plane: i32, nt: i32, photons: f32, cutR2: i32,\n   wx: vec4<f32>, wy: vec4<f32>,\n};\n\n@group(0) @binding(0) var<uniform> P: Params;\n@group(0) @binding(1) var<storage, read> S0: array<f32>;\n@group(0) @binding(2) var<storage, read> S1: array<f32>;\n@group(0) @binding(3) var<storage, read> S2: array<f32>;\n@group(0) @binding(4) var<storage, read> S3: array<f32>;\n@group(0) @binding(5) var<storage, read> Stat: array<u32>;\n@group(0) @binding(6) var<storage, read> Dyn: array<u32>;\n@group(0) @binding(7) var<storage, read_write> Out: array<u32>;\n\n// One emitter's taps from block-sum plane `base` (one function per kernel buffer: WGSL passes no storage pointers).\nfn taps0(base: u32, r0: i32, c0: i32, bw: i32, em: Em) -> f32\n{\n   var s = 0.0;\n   for (var j = 0; j < em.nt; j++)\n   {\n      let r = r0 + j;\n      if (r < 0 || r >= bw) { continue; }\n      var row = 0.0;\n      for (var ii = 0; ii < em.nt; ii++)\n      {\n         let c = c0 + ii;\n         if (c >= 0 && c < bw) { row += em.wx[ii] * S0[base + u32(r * bw + c)]; }\n      }\n      s += em.wy[j] * row;\n   }\n   return s;\n}\nfn taps1(base: u32, r0: i32, c0: i32, bw: i32, em: Em) -> f32\n{\n   var s = 0.0;\n   for (var j = 0; j < em.nt; j++)\n   {\n      let r = r0 + j;\n      if (r < 0 || r >= bw) { continue; }\n      var row = 0.0;\n      for (var ii = 0; ii < em.nt; ii++)\n      {\n         let c = c0 + ii;\n         if (c >= 0 && c < bw) { row += em.wx[ii] * S1[base + u32(r * bw + c)]; }\n      }\n      s += em.wy[j] * row;\n   }\n   return s;\n}\nfn taps2(base: u32, r0: i32, c0: i32, bw: i32, em: Em) -> f32\n{\n   var s = 0.0;\n   for (var j = 0; j < em.nt; j++)\n   {\n      let r = r0 + j;\n      if (r < 0 || r >= bw) { continue; }\n      var row = 0.0;\n      for (var ii = 0; ii < em.nt; ii++)\n      {\n         let c = c0 + ii;\n         if (c >= 0 && c < bw) { row += em.wx[ii] * S2[base + u32(r * bw + c)]; }\n      }\n      s += em.wy[j] * row;\n   }\n   return s;\n}\nfn taps3(base: u32, r0: i32, c0: i32, bw: i32, em: Em) -> f32\n{\n   var s = 0.0;\n   for (var j = 0; j < em.nt; j++)\n   {\n      let r = r0 + j;\n      if (r < 0 || r >= bw) { continue; }\n      var row = 0.0;\n      for (var ii = 0; ii < em.nt; ii++)\n      {\n         let c = c0 + ii;\n         if (c >= 0 && c < bw) { row += em.wx[ii] * S3[base + u32(r * bw + c)]; }\n      }\n      s += em.wy[j] * row;\n   }\n   return s;\n}\n\nfn pcg4d(v0: vec4<u32>) -> vec4<u32>\n{\n   var v = v0 * 1664525u + 1013904223u;\n   v.x += v.y * v.w; v.y += v.z * v.x; v.z += v.x * v.y; v.w += v.y * v.z;\n   v ^= v >> vec4<u32>(16u);\n   v.x += v.y * v.w; v.y += v.z * v.x; v.z += v.x * v.y; v.w += v.y * v.z;\n   return v;\n}\n\nvar<private> gFrame: u32;\nvar<private> gPix: u32;\nvar<private> gCtr: u32;\nvar<private> gBuf: vec4<u32>;\nvar<private> gK: u32;\n\nfn uniform01() -> f32\n{\n   if (gK == 4u)\n   {\n      gBuf = pcg4d(vec4<u32>(P.Seed, gFrame, gPix, gCtr));\n      gCtr++;\n      gK = 0u;\n   }\n   let x = gBuf[gK];\n   gK++;\n   return (f32(x >> 9u) + 0.5) * 1.1920928955078125e-7;\n}\n\nfn gauss() -> f32\n{\n   let r = sqrt(-2.0 * log(uniform01()));\n   return r * cos(6.283185307179586 * uniform01());\n}\n\nfn poisson(l: f32) -> f32\n{\n   if (l > 60.0) { return max(0.0, floor(l + sqrt(l) * gauss() + 0.5)); }\n   if (!(l > 0.0)) { return 0.0; }\n   let L = exp(-l);\n   var k = 0;\n   var p = 1.0;\n   loop\n   {\n      k++;\n      p *= uniform01();\n      if (!(p > L && k < 1000)) { break; }\n   }\n   return f32(k - 1);\n}\n\nfn gammaDraw(k: f32) -> f32\n{\n   let d = k - 1.0 / 3.0;\n   let c = 1.0 / sqrt(9.0 * d);\n   for (var it = 0; it < 1000; it++)\n   {\n      let x = gauss();\n      let t = 1.0 + c * x;\n      if (t <= 0.0) { continue; }\n      let v = t * t * t;\n      let w = uniform01();\n      if (w < 1.0 - 0.0331 * x * x * x * x) { return d * v; }\n      if (log(w) < 0.5 * x * x + d * (1.0 - v + log(v))) { return d * v; }\n   }\n   return d;\n}\n\nfn emAt(e: u32) -> Em\n{\n   let a = P.EmAt + 16u * e;\n   var em: Em;\n   em.x0 = bitcast<i32>(Dyn[a]);\n   em.y0 = bitcast<i32>(Dyn[a + 1u]);\n   em.bx = bitcast<i32>(Dyn[a + 2u]);\n   em.by = bitcast<i32>(Dyn[a + 3u]);\n   em.plane = bitcast<i32>(Dyn[a + 4u]);\n   em.nt = bitcast<i32>(Dyn[a + 5u]);\n   em.photons = bitcast<f32>(Dyn[a + 6u]);\n   em.cutR2 = bitcast<i32>(Dyn[a + 7u]);\n   em.wx = vec4<f32>(bitcast<f32>(Dyn[a + 8u]), bitcast<f32>(Dyn[a + 9u]), bitcast<f32>(Dyn[a + 10u]), bitcast<f32>(Dyn[a + 11u]));\n   em.wy = vec4<f32>(bitcast<f32>(Dyn[a + 12u]), bitcast<f32>(Dyn[a + 13u]), bitcast<f32>(Dyn[a + 14u]), bitcast<f32>(Dyn[a + 15u]));\n   return em;\n}\n\n// The group's 16 x 16 pixels (a tile) share the tile's emitter list: the frame's emitters whose footprint (the kernel's\n// halo spans, its cut radius) reaches the tile, in the frame's order, made by the host (2026-11-24: every group walked\n// the whole frame's list, ~16 ns a pixel on an A40 at a few thousand blinks a frame -- as slow as 32 CPU cores).\n// Staged through workgroup memory in chunks of 256 (one record per invocation, 16 KB: WebGPU's default limit), so a\n// record is read once per group, not once per pixel. A pixel sums the same emitters in the same order as before.\nconst CHUNK = 256u;\nvar<workgroup> sEm: array<Em, 256>;\nvar<workgroup> sCount: u32;\nvar<workgroup> sStart: u32;\n\n@compute @workgroup_size(16, 16, 1)\nfn splat_frames(@builtin(global_invocation_id) id: vec3<u32>, @builtin(local_invocation_index) li: u32,\n                @builtin(workgroup_id) gid: vec3<u32>)\n{\n   // Every invocation of the group takes part in the staging (barriers), also those outside the frame; one group is\n   // one frame (gid.z < NFrames).\n   let inside = id.x < P.W && id.y < P.H;\n   let i = id.y * P.W + id.x;\n   var px = vec4<f32>(0.0, 0.0, 1.0, 0.0);\n   if (inside)\n   {\n      px = vec4<f32>(bitcast<f32>(Stat[4u * i]), bitcast<f32>(Stat[4u * i + 1u]), bitcast<f32>(Stat[4u * i + 2u]),\n                     bitcast<f32>(Stat[4u * i + 3u]));\n   }\n   let fa = 32u + 8u * gid.z;\n   // The tile's list: Dyn[tileAt + t] .. Dyn[tileAt + t + 1] are the word positions of its emitter numbers.\n   let tileAt = Dyn[fa + 5u];\n   let t = gid.y * ((P.W + 15u) / 16u) + gid.x;\n   if (li == 0u)\n   {\n      sStart = Dyn[tileAt + t];\n      sCount = Dyn[tileAt + t + 1u] - Dyn[tileAt + t];\n   }\n   let emCount = workgroupUniformLoad(&sCount);\n   let listStart = workgroupUniformLoad(&sStart);\n   let frame = Dyn[fa + 2u];\n   let bgScale = bitcast<f32>(Dyn[fa + 3u]);\n   let extra = Dyn[fa + 4u];\n\n   // Splat: gather this frame's emitters, in list order, onto this pixel.\n   var acc = px.w * bgScale;\n   let X = i32(id.x);\n   let Y = i32(id.y);\n   for (var e0 = 0u; e0 < emCount; e0 += CHUNK)\n   {\n      let cnt = min(CHUNK, emCount - e0);\n      if (li < cnt) { sEm[li] = emAt(Dyn[listStart + e0 + li]); }\n      workgroupBarrier();\n      for (var k = 0u; k < cnt; k++)\n      {\n         let em = sEm[k];\n         let kk = u32(em.plane) >> 16u;\n         let g = vec4<i32>(bitcast<i32>(Dyn[4u * kk]), bitcast<i32>(Dyn[4u * kk + 1u]), bitcast<i32>(Dyn[4u * kk + 2u]),\n                           bitcast<i32>(Dyn[4u * kk + 3u]));   // camRad, os, bw, off\n         let dx = X - em.x0;\n         let dy = Y - em.y0;\n         if (!inside || abs(dx) > g.x || abs(dy) > g.x) { continue; }\n         if (dx * dx + dy * dy > em.cutR2) { continue; }\n         let q = vec4<u32>(Dyn[16u + 4u * kk], Dyn[17u + 4u * kk], Dyn[18u + 4u * kk], Dyn[19u + 4u * kk]);\n         let plane = u32(em.plane) & 0xffffu;\n         if (q.y != 0u)\n         {\n            let sa = P.SpanAt + 2u * (q.z + plane * u32(2 * g.x + 1) + u32(dy + g.x));\n            if (dx < bitcast<i32>(Stat[sa]) || dx > bitcast<i32>(Stat[sa + 1u])) { continue; }\n         }\n         let r0 = em.by + dy * g.y + g.w;\n         let c0 = em.bx + dx * g.y + g.w;\n         let base = plane * q.x;\n         var s: f32;\n         if (q.w == 0u) { s = taps0(base, r0, c0, g.z, em); }\n         else if (q.w == 1u) { s = taps1(base, r0, c0, g.z, em); }\n         else if (q.w == 2u) { s = taps2(base, r0, c0, g.z, em); }\n         else { s = taps3(base, r0, c0, g.z, em); }\n         acc += em.photons * s;\n      }\n      workgroupBarrier();\n   }\n   if (!inside) { return; }\n   if (extra != 0xffffffffu) { acc += bitcast<f32>(Dyn[extra + i]); }\n\n   // Noise: this pixel's own counter stream (a window's pixels at their place on the sensor).\n   gFrame = frame;\n   gPix = P.PixBase + i;\n   gCtr = 0u;\n   gK = 4u;\n   gBuf = vec4<u32>(0u);\n   let photons = max(acc, 0.0);\n   var adu: f32;\n   if (P.Emccd != 0u)\n   {\n      let ne = poisson(photons * P.Qe + P.Dark + P.Cic);\n      var o = 0.0;\n      if (ne > 0.0) { o = gammaDraw(ne); }\n      adu = floor(px.x + (o + (px.z / P.EmGain) * gauss()) / px.y + 0.5);\n      adu = clamp(adu, 0.0, P.MaxAdu);\n   }\n   else\n   {\n      let ne = poisson(photons * P.Qe + P.Dark);\n      adu = px.x + (ne + px.z * gauss()) / px.y;\n      adu = floor(clamp(adu, 0.0, 65535.0) + 0.5);\n   }\n   Out[gid.z * P.W * P.H + i] = u32(adu);\n}\n";
